This is the simple version. It tries each possible starting position and checks the whole pattern character by character. It does not use hashing, but it is easy to verify and still handles overlapping matches.

For example, with `txt = "aaaa"` and `pat = "aa"`, the valid starts are 0, 1, and 2. If no position works, the required result is `[-1]`.

```java
import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> search(String pat, String txt) {
        List<Integer> result = new ArrayList<>();
        int patternLength = pat.length();
        int textLength = txt.length();

        if (patternLength == 0 || patternLength > textLength) {
            result.add(-1);
            return result;
        }

        for (int start = 0; start <= textLength - patternLength; start++) {
            int offset = 0;
            while (offset < patternLength &&
                   txt.charAt(start + offset) == pat.charAt(offset)) {
                offset++;
            }

            if (offset == patternLength) {
                result.add(start);
            }
        }

        if (result.isEmpty()) {
            result.add(-1);
        }
        return result;
    }
}
```

The worst-case time is `O((n - m + 1) * m)`, which is `O(nm)`. It uses `O(1)` extra space besides the output list. Empty patterns are treated as having no valid search result here.

Instead of comparing every window from the beginning, this version uses the prefix function from KMP. The prefix table says how much of the pattern is still useful after a mismatch. It is a different linear-time way to solve the same search task.

The combined string is `pattern + separator + text`. Whenever the prefix value reaches the pattern length, a match ends at that position. The separator is not part of either input, so it cannot join the two strings by accident.

```java
import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> search(String pat, String txt) {
        List<Integer> result = new ArrayList<>();
        int patternLength = pat.length();

        if (patternLength == 0 || patternLength > txt.length()) {
            result.add(-1);
            return result;
        }

        String combined = pat + "{" + txt;
        int[] prefix = new int[combined.length()];

        for (int i = 1; i < combined.length(); i++) {
            int matched = prefix[i - 1];
            while (matched > 0 && combined.charAt(i) != combined.charAt(matched)) {
                matched = prefix[matched - 1];
            }
            if (combined.charAt(i) == combined.charAt(matched)) {
                matched++;
            }
            prefix[i] = matched;

            if (matched == patternLength) {
                int start = i - 2 * patternLength;
                result.add(start);
            }
        }

        if (result.isEmpty()) {
            result.add(-1);
        }
        return result;
    }
}
```

The time cost is `O(n + m)` and the extra space is `O(n + m)` for the combined string and prefix table. A pattern longer than the text and a missing pattern both return `[-1]`.

This version keeps two rolling hashes for every window. A match is accepted only when both hashes agree and the actual substring also equals the pattern. Using two hashes makes accidental matches very unlikely, while the final comparison handles collisions completely.

Dry run: for `txt = "aaaaa"` and `pat = "aaa"`, the window starts are 0, 1, and 2. Every one is reported, so overlap is not skipped.

The input strings are not changed by the code.

```cpp
#include <string>
#include <vector>
using namespace std;

class Solution{
public:
    vector <int> search(string pat, string txt) {
        vector<int> result;
        int m = pat.size();
        int n = txt.size();

        if (m == 0 || m > n) {
            return {-1};
        }

        const long long base = 911382323LL;
        const long long mod1 = 1000000007LL;
        const long long mod2 = 1000000009LL;
        long long power1 = 1;
        long long power2 = 1;
        long long pattern1 = 0;
        long long pattern2 = 0;
        long long window1 = 0;
        long long window2 = 0;

        for (int i = 0; i < m - 1; i++) {
            power1 = (power1 * base) % mod1;
            power2 = (power2 * base) % mod2;
        }

        for (int i = 0; i < m; i++) {
            pattern1 = (pattern1 * base + pat[i]) % mod1;
            pattern2 = (pattern2 * base + pat[i]) % mod2;
            window1 = (window1 * base + txt[i]) % mod1;
            window2 = (window2 * base + txt[i]) % mod2;
        }

        for (int start = 0; start <= n - m; start++) {
            if (pattern1 == window1 && pattern2 == window2 &&
                txt.compare(start, m, pat) == 0) {
                result.push_back(start);
            }

            if (start < n - m) {
                window1 = (window1 - txt[start] * power1) % mod1;
                window2 = (window2 - txt[start] * power2) % mod2;

                if (window1 < 0) window1 += mod1;
                if (window2 < 0) window2 += mod2;

                window1 = (window1 * base + txt[start + m]) % mod1;
                window2 = (window2 * base + txt[start + m]) % mod2;
            }
        }

        if (result.empty()) {
            return {-1};
        }
        return result;
    }
};
```

The rolling work takes `O(n + m)` time on average. Extra working space is `O(1)`, not counting the vector of returned positions. The direct string check keeps the result correct even if a hash collision occurs.

I kept the rolling hash in a 64-bit integer and used a prime modulus to keep values small. When the hash of the current window matches the pattern hash, the code still compares the strings, so a hash collision cannot create a wrong answer.

The window moves one character at a time. This also finds overlapping matches, such as `ana` inside `banana` at positions 1 and 3.

```cpp
#include <string>
#include <vector>
using namespace std;

class Solution{
public:
    vector <int> search(string pat, string txt) {
        vector<int> result;
        int patternLength = pat.size();
        int textLength = txt.size();

        if (patternLength == 0 || patternLength > textLength) {
            return {-1};
        }

        const long long mod = 1000000007LL;
        const long long base = 256;
        long long patternHash = 0;
        long long windowHash = 0;
        long long highestPower = 1;

        for (int i = 0; i < patternLength - 1; i++) {
            highestPower = (highestPower * base) % mod;
        }

        for (int i = 0; i < patternLength; i++) {
            patternHash = (patternHash * base + pat[i]) % mod;
            windowHash = (windowHash * base + txt[i]) % mod;
        }

        for (int start = 0; start <= textLength - patternLength; start++) {
            if (patternHash == windowHash &&
                txt.compare(start, patternLength, pat) == 0) {
                result.push_back(start);
            }

            if (start < textLength - patternLength) {
                windowHash = (windowHash - txt[start] * highestPower) % mod;
                if (windowHash < 0) {
                    windowHash += mod;
                }
                windowHash = (windowHash * base + txt[start + patternLength]) % mod;
            }
        }

        if (result.empty()) {
            return {-1};
        }
        return result;
    }
};
```

Time complexity is `O(n + m)` on average, with `n` as the text length and `m` as the pattern length. The extra space is `O(1)`, apart from the returned indices.
